-- ============================================================================
-- SheetLayout AI — Unit 1 Parts & RM Import Script
-- Fixes incompatible data issues: clean types, foreign keys, and no duplicates
-- ============================================================================

-- 1. Ensure all Unit 1 Raw Material standards exist in public.rm first
-- (Prevents Foreign Key violation on standard_rm REFERENCES rm(rm_code))


-- 2. Insert or update 443 clean Unit 1 Parts into public.parts

ON CONFLICT (part_no) 
DO UPDATE SET
    company_id          = EXCLUDED.company_id,
    part_desc           = EXCLUDED.part_desc,
    grade               = EXCLUDED.grade,
    thickness           = EXCLUDED.thickness,
    length              = EXCLUDED.length,
    width               = EXCLUDED.width,
    weight              = EXCLUDED.weight,
    offtake             = EXCLUDED.offtake,
    strip_per_blank_qty = EXCLUDED.strip_per_blank_qty,
    standard_rm         = EXCLUDED.standard_rm,
    updated_at          = now();
